import{_ as r,C as s,o as n,c as i,j as e,a as o,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const l="/videos/picker-report-loop.mp4",y=JSON.parse('{"title":"Record a bug report","description":"Record the steps to a bug in Piwi Picker, mark what the page gets wrong, and get a failing Playwright test, a Markdown report and a `.piwibug` file with the evidence, with no Piwi instance.","frontmatter":{"title":"Record a bug report","description":"Record the steps to a bug in Piwi Picker, mark what the page gets wrong, and get a failing Playwright test, a Markdown report and a `.piwibug` file with the evidence, with no Piwi instance.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/report-a-bug.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/report-a-bug.html"}],["meta",{"property":"og:title","content":"Record a bug report | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Record the steps to a bug in Piwi Picker, mark what the page gets wrong, and get a failing Playwright test, a Markdown report and a `.piwibug` file with the evidence, with no Piwi instance."}]]},"headers":[],"relativePath":"features/report-a-bug.md","filePath":"features/report-a-bug.md","lastUpdated":1795606445000}'),c={name:"features/report-a-bug.md"};function p(g,t,u,w,f,m){const a=s("Needs");return n(),i("div",null,[t[0]||(t[0]=e("h1",{id:"record-a-bug-report",tabindex:"-1"},[o("Record a bug report "),e("a",{class:"header-anchor",href:"#record-a-bug-report","aria-label":'Permalink to "Record a bug report"'},"​")],-1)),h(a,{extension:""}),t[1]||(t[1]=e("p",null,[o("Reproduce a bug in your browser, say what the page should show, and get the test that proves it. A "),e("a",{href:"./record-actions.html"},"recording"),o(" of the "),e("a",{href:"./extension.html"},"Piwi Picker extension"),o(' becomes a bug report as soon as you mark something on the page as wrong ("this should read Total: 36.00"): it then hands you a failing Playwright test, a Markdown report and a '),e("code",null,".piwibug"),o(" file for the developer, with the evidence every recording collects. Everything is built in your browser; nothing is sent anywhere unless you send it to your Piwi instance. This page covers marking what is wrong and what a report holds, with no instance; "),e("a",{href:"./replay-a-bug-report.html"},"Replay a recording"),o(" plays one again, and "),e("a",{href:"./bug-reports.html"},"Bug reports on your instance"),o(" covers what an instance does with one sent to it.")],-1)),t[2]||(t[2]=e("figure",null,[e("video",{src:l,autoplay:"",loop:"",muted:"",playsinline:"",controls:"","aria-label":"Recording a bug on a cart page: a coupon applied, the total checked with what it should read instead of what it shows, then Finish opens the report with its steps, its evidence and a failing test to copy"}),e("figcaption",null,"Reproduce it, say what the page should show, finish: the report and its failing test.")],-1)),t[3]||(t[3]=d('<h2 id="marking-what-is-wrong" tabindex="-1">Marking what is wrong <a class="header-anchor" href="#marking-what-is-wrong" aria-label="Permalink to &quot;Marking what is wrong&quot;">​</a></h2><p>Open the popup on the page where the flow starts, choose <strong>Record</strong> (<code>1</code>) as <a href="./record-actions.html">Record a test</a> describes, and reproduce the bug. These tools of the recording bar say what is wrong:</p><ul><li><strong>Check an element</strong>: pick the element, then choose what to check: its text, its value or its name as screen readers announce it. The dialog shows what the page shows now and an <strong>Expected</strong> field holding the same value: type what it should be instead. For a state, choose the one the element should be in and is not, such as <strong>It should be hidden</strong> or <strong>It should be grayed out, not usable</strong>.</li><li><strong>Check the address</strong>: type the path the flow should have reached, such as <code>/checkout/thanks</code>, in place of the one the page is on.</li><li><strong>Something is missing</strong>: say what should be there (a button, a link, a title, a text field, a dropdown, …) and its name, such as a button named &quot;Download invoice&quot;. Piwi Picker looks for it on the page first and refuses one that is there already; use Check an element for that one.</li></ul><p>Before you press <strong>Add the check</strong>, the dialog says which of the two it will record: a check that passes, or the page marked as wrong, which makes the recording a bug report whose test fails until the page shows what you expect. Once it is wrong, a <strong>Note</strong> field takes what happened, in your words. Each becomes a step of the recording, in place, with what the page showed. <strong>Finish</strong> ends the recording and opens the report.</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h2><p>Every recording keeps, whether or not anything is marked wrong:</p><ul><li><strong>Console errors and warnings</strong>, uncaught errors and unhandled promise rejections, with the page they happened on.</li><li><strong>Failed requests</strong>: the method, the path, and the status of any request that failed or answered 400 or more: in Chrome and Edge, documents, scripts and images included; elsewhere, the page&#39;s <code>fetch</code> and <code>XMLHttpRequest</code> calls. Query values are removed (<code>/api/cart/coupon?code=&lt;redacted&gt;</code>), ids and tokens in the path are collapsed as Piwi does for routes, and no header or body is ever read.</li><li><strong>An outline of the page</strong> around the element marked wrong, or of the page at <strong>Finish</strong> when nothing was: roles, names, states and field values, in the YAML form Playwright&#39;s ARIA snapshots use, at most 400 lines. Piwi Picker builds it from its own reading of the page, so it is an outline, not Playwright&#39;s snapshot. Password fields, and fields for a card number, its security code or a one-time code, never show their value.</li><li><strong>Screenshots</strong>, when something is marked wrong, at <strong>Finish</strong> and when you ask for one, three at most.</li><li><strong>A screenshot of each step</strong>: the page as the step began, with the element it acts on, for whoever has to <a href="./replay-a-bug-report.html#when-a-step-cannot-be-played">play that step by hand</a>. They show the whole page: leave them out in the report if they show what should not be shared. Taken through the debugging protocol, so mostly in Chrome and Edge.</li><li><strong>The context</strong>: the page, the browser and its version, the time and the extension&#39;s version.</li><li><strong>The viewport size</strong>: at the start, then after each resize or zoom change, with the zoom when it is not 100%. The test sets it with <code>page.setViewportSize</code> before the step it applies from, so a bug seen on a narrow window reproduces at that width.</li></ul><p>The first 100 console entries and 100 failed requests are kept; the report counts the rest.</p><h3 id="how-the-evidence-is-collected" tabindex="-1">How the evidence is collected <a class="header-anchor" href="#how-the-evidence-is-collected" aria-label="Permalink to &quot;How the evidence is collected&quot;">​</a></h3><p>In Chrome and Edge, Piwi Picker reads the console, the requests and the screenshots of the tab the recording started in through the browser&#39;s <a href="./extension.html#the-debugging-bar">debugging protocol</a>, from the page&#39;s first script, on every page of the recording. Chrome&#39;s debugging bar shows from the start until you finish; the recording bar says it is expected, and adds a <strong>Screenshot</strong> button.</p><p>Elsewhere (Firefox, the site&#39;s other tabs, or once the bar is cancelled), a small script added to the page itself wraps <code>console.error</code>, <code>console.warn</code>, <code>fetch</code> and <code>XMLHttpRequest</code> without changing what they do, under the same site access as recording, and is removed when you finish or discard the recording. A screenshot then needs the <code>activeTab</code> grant: it works from the click that started the recording until the tab moves to another page; after that, open Piwi Picker on the tab and choose <strong>Take a screenshot</strong> (<code>S</code>), which takes Replay&#39;s place in the popup while a recording runs.</p><h2 id="the-report" tabindex="-1">The report <a class="header-anchor" href="#the-report" aria-label="Permalink to &quot;The report&quot;">​</a></h2><p><strong>Finish</strong> opens the recording&#39;s <a href="./record-actions.html#the-finish-panel">finish panel</a> as a report: a title to write, the steps with the wrong ones highlighted, and a line summing up the evidence.</p><ul><li><strong>Copy failing test</strong>, in place of <strong>Copy test</strong>, copies a Playwright spec for your suite, marked <code>test.fail()</code> so it keeps your CI green while the bug exists, tagged <code>@bug</code>, with paths instead of the recorded URLs, the most stable locator recorded for each element and, with a connection, calls to your test functions. What it holds, and what to do once it passes: <a href="./bug-reports.html#the-failing-test">The failing test</a>.</li><li><strong>Copy report</strong> copies the report as Markdown, for an issue or a message: the steps in plain words, what was expected and what the page showed, the notes, the console entries, the failed requests and the outline.</li><li><strong>Download .piwibug</strong> saves it all as one <a href="/reference/bug-report-file.html">file</a>, which Replay and the <a href="./desktop.html#importing-local-files">desktop app</a> open. It is a zip archive: rename it to <code>.zip</code> to look inside, or to attach it to a GitHub issue. <a href="/reference/cli.html#codegen"><code>piwi codegen</code></a> renders its <code>steps.json</code> for any project.</li></ul><p>Typed values stay as you typed them, except passwords, card numbers, their security codes and one-time codes, which are never recorded: the spec reads them from an environment variable. Look over the report before you share it.</p><p>With the extension connected to an instance, <strong>Send to Piwi…</strong> sends the report after a preview. It shows once a step is marked wrong: a recording that marks nothing wrong is no bug report. See <a href="./bug-reports.html#sending-a-report">Sending a report</a>.</p><h2 id="replaying-a-report" tabindex="-1">Replaying a report <a class="header-anchor" href="#replaying-a-report" aria-label="Permalink to &quot;Replaying a report&quot;">​</a></h2><p><strong>Replay</strong>, on the finished report or from the popup (<code>R</code>), plays the steps again in a tab and says whether the bug shows there: see <a href="./replay-a-bug-report.html">Replay a recording</a>.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>It follows one site, like any <a href="./record-actions.html">recording</a>, in the top-level document only.</li><li>Without the debugging protocol, only the page&#39;s own <code>fetch</code> and <code>XMLHttpRequest</code> calls are seen: not images, stylesheets, a form that loads a new page, or a request made by a worker.</li><li>A recording sends nothing anywhere: only <strong>Send to Piwi…</strong> does, after showing what it sends.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./record-actions.html">Record a test</a>: the recording, its bar and its finish panel</li><li><a href="./replay-a-bug-report.html">Replay a recording</a>: playing a report again, in the browser or with Playwright</li><li><a href="/reference/steps-format.html">Steps file</a>: the format of <code>steps.json</code></li><li><a href="/reference/bug-report-file.html">Bug report file</a>: what a <code>.piwibug</code> holds</li><li><a href="/reference/cli.html#codegen">CLI: codegen</a>: a steps file rendered as a spec for your project</li><li><a href="./extension.html">Browser extension</a>: every tool of Piwi Picker</li></ul>',22))])}const k=r(c,[["render",p]]);export{y as __pageData,k as default};
